    fn threshold_secs_unset_uses_default() {
        assert_eq!(
            parse_threshold_secs_or_refuse("BASTION_ACCESS_STALL_SECS", None, 120.0),
            120.0
        );
    }

    /// A1: set and valid -> that value, not the default.
